import { Component, inject } from '@angular/core';
import { Session } from '../../core/session';
import { PeopleList } from '../people/people-list';
import { SettingsForm } from '../settings/settings-form';
import { SheetBar } from '../session/sheet-bar';
import { SignIn } from '../session/signin';

// The one screen: sign in by name, then load a sheet by id and keep its people.
@Component({
  selector: 'app-home',
  imports: [SignIn, SheetBar, SettingsForm, PeopleList],
  template: `
    @if (session.user()) {
      <app-sheet-bar />
      @if (!session.sheetId()) {
        <p data-testid="home-empty">Nothing here yet.</p>
      } @else {
        <app-settings-form />
        <app-people-list />
      }
    } @else {
      <app-signin />
    }
  `,
})
export class Home {
  protected readonly session = inject(Session);
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session } from './session';

export interface Settings {
  /** The most due a clerk may settle, as text with two decimals; null when there is no limit. */
  clerkLimit: string | null;
  /** The least live due a claim has, as text with two decimals. */
  floor: string;
}

export type RoleName = 'clerk' | 'steward';

export interface Role {
  user: string;
  role: RoleName;
}

/** The roles a user name can be given; a name given none is a clerk. */
export const ROLES: RoleName[] = ['clerk', 'steward'];

/** A limit with up to two decimals, 0.00 or more. */
export const LIMIT = /^\d{1,12}(\.\d{1,2})?$/;

// The settings of the active sheet and the roles it gives user names.
@Injectable({ providedIn: 'root' })
export class SheetSettings {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  get(sheetId: string): Promise<Settings> {
    return firstValueFrom(this.http.get<Settings>(`${this.url(sheetId)}/settings`));
  }

  roles(sheetId: string): Promise<Role[]> {
    return firstValueFrom(this.http.get<Role[]>(`${this.url(sheetId)}/roles`));
  }

  /** Set the clerk limit; null for no limit. */
  setClerkLimit(value: string | null): Promise<Settings> {
    const [sheetId, headers] = this.active();
    return firstValueFrom(this.http.put<Settings>(`${this.url(sheetId)}/settings/clerk-limit`, { value }, { headers }));
  }

  /** Set the floor. */
  setFloor(value: string): Promise<Settings> {
    const [sheetId, headers] = this.active();
    return firstValueFrom(this.http.put<Settings>(`${this.url(sheetId)}/settings/floor`, { value }, { headers }));
  }

  /** Give a user name a role, replacing the one it had. */
  setRole(user: string, role: RoleName): Promise<Role> {
    const [sheetId, headers] = this.active();
    return firstValueFrom(
      this.http.put<Role>(`${this.url(sheetId)}/roles/${encodeURIComponent(user)}`, { role }, { headers }),
    );
  }

  private active(): [string, { 'X-User': string }] {
    const sheetId = this.session.sheetId();
    const user = this.session.user();
    if (!sheetId || !user) throw new Error('no sheet loaded');
    return [sheetId, { 'X-User': user }];
  }

  private url(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}`;
  }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Grade, Person } from './people';
import { Rate, atLeast, due, pctOn } from './rates';
import { Session } from './session';

/** Where a claim is in its life: DRAFT, then OPEN, then SETTLED; a DRAFT or OPEN claim may be VOID. */
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'SETTLED' | 'VOID';

/** A change of status a claim can be asked for. */
export type ClaimAction = 'open' | 'settle' | 'void';

/** Whether a claim at this status counts toward claimed, due-total and every total. */
export function counts(c: Claim): boolean {
  return c.status === 'OPEN' || c.status === 'SETTLED';
}

/** Whether a claim counts in the live totals: it counts, and it is not an open claim of a person
 *  on hold. */
export function countsLive(c: Claim, held: boolean): boolean {
  return counts(c) && !(held && c.status === 'OPEN');
}

export interface Claim {
  id: number;
  personId: number;
  /** The amount as text with two decimals. */
  amount: string;
  date: string;
  note: string;
  status: ClaimStatus;
  /** The claim's number on the sheet, given when it is opened; null for a draft or a void claim. */
  number: number | null;
  /** The due fixed when the claim was settled, as text with two decimals; null when it is not
   *  settled, or was settled while its person's grade had no rate (its due then stays live). */
  settledDue: string | null;
  /** Who opened the claim; null when it was never opened. That user cannot settle it. */
  openedBy: string | null;
  /** Whether its person's last statement bound it to the due it had then. */
  stated: boolean;
  /** The due the last statement bound it to, as text with two decimals; null when it is unbound,
   *  or was bound while it had no due (its due then stays live). */
  statedDue: string | null;
}

export interface ClaimForm {
  amount: string;
  /** yyyy-mm-dd, or null for the sheet's today. */
  date: string | null;
  note: string;
}

